#!/usr/bin/env python3
"""Dump Python TTP's start/end/ordinary partition for every group of a set of templates.

The expectations for internal/compiler/profile_test.go come from this script,
so the indicator profile follows Python TTP 0.10.1 rule for rule. It loads each
template in TTP, walks every group, and records, in template-line order, which
of TTP's three lists each regex landed in (start_re / end_re / re), its ACTION
and its IS_LINE flag.

TTP keeps the three lists but not the line order, so the script tags every
regex dict with its ordinal as get_regexes appends it: the partition loop
appends in line order, the group's own text first and then each child's tail.

Templates come from:
  - cases/*.ttp next to this script (curated edge cases), and
  - every case template in test/ttpsuite/testdata/cases/*.json (broad sweep).

Usage (TTP pinned in test/comparison/requirements.txt):
  python -I internal/compiler/testdata/indicatorprofile/dump_ttp_profile.py          # rewrite expected.json
  python -I internal/compiler/testdata/indicatorprofile/dump_ttp_profile.py --check  # exit 1 if it would change
"""

import argparse
import importlib.metadata
import glob
import json
import logging
import os
import sys

from ttp import ttp
from ttp.ttp import _group_class

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.abspath(os.path.join(HERE, "..", "..", "..", ".."))
SUITE_CASES = os.path.join(REPO, "test", "ttpsuite", "testdata", "cases")
SUITE_CWD = os.path.join(REPO, "test", "ttpsuite", "testdata", "pytest")
OUT = os.path.join(HERE, "expected.json")


class _OrdinalList(list):
    """List that stamps each appended regex dict with the group's next ordinal."""

    def __init__(self, owner):
        super().__init__()
        self._owner = owner

    def append(self, item):
        item["_ord"] = self._owner._profile_next
        self._owner._profile_next += 1
        super().append(item)


_original_get_regexes = _group_class.get_regexes


def _recording_get_regexes(self, data, tail=False):
    if not isinstance(self.start_re, _OrdinalList):
        self._profile_next = 0
        self.start_re = _OrdinalList(self)
        self.end_re = _OrdinalList(self)
        self.re = _OrdinalList(self)
    return _original_get_regexes(self, data, tail=tail)


_group_class.get_regexes = _recording_get_regexes


def group_profile(group):
    entries = []
    for role, items in (("start", group.start_re), ("end", group.end_re), ("ordinary", group.re)):
        for item in items:
            entries.append(
                {
                    "ord": item["_ord"],
                    "role": role,
                    "action": item["ACTION"],
                    "is_line": bool(item["IS_LINE"]),
                }
            )
    entries.sort(key=lambda e: e["ord"])
    for e in entries:
        del e["ord"]
    out = {"name": group.name, "method": group.method, "patterns": entries}
    if group.children:
        out["children"] = [group_profile(child) for child in group.children]
    return out


def template_groups(template_obj):
    """Groups in gottp's order: the template's own groups, then each child template's (flattened)."""
    groups = [group_profile(g) for g in template_obj.groups]
    for child in getattr(template_obj, "templates", []):
        groups += template_groups(child)
    return groups


def dump(template_text):
    parser = ttp(template=template_text, log_level="CRITICAL")
    groups = []
    for template_obj in parser._templates:
        groups += template_groups(template_obj)
    return groups


def collect():
    templates = {}
    for path in sorted(glob.glob(os.path.join(HERE, "cases", "*.ttp"))):
        name = "cases/" + os.path.splitext(os.path.basename(path))[0]
        with open(path, encoding="utf-8") as f:
            templates[name] = f.read()
    for path in sorted(glob.glob(os.path.join(SUITE_CASES, "*.json"))):
        with open(path, encoding="utf-8") as f:
            for case in json.load(f):
                templates["ttpsuite/" + case["name"]] = case["template"]
    return templates


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--check", action="store_true", help="exit 1 if expected.json would change")
    args = ap.parse_args()

    logging.disable(logging.CRITICAL)
    version = importlib.metadata.version("ttp")
    if version != "0.10.1":
        print("need Python TTP 0.10.1, found {}".format(version), file=sys.stderr)
        return 1
    templates = collect()
    result = {"_comment": "Generated by dump_ttp_profile.py from Python TTP; do not edit by hand.", "templates": {}}
    os.chdir(SUITE_CWD)  # suite templates read ./assets/... relative to here
    for name, text in templates.items():
        try:
            result["templates"][name] = {"groups": dump(text)}
        except BaseException as e:  # TTP raises SystemExit on some bad templates
            result["templates"][name] = {"error": type(e).__name__}
    text = json.dumps(result, indent=1, sort_keys=True) + "\n"
    if args.check:
        with open(OUT, encoding="utf-8") as f:
            if f.read() != text:
                print("expected.json is out of date; rerun without --check", file=sys.stderr)
                return 1
        return 0
    with open(OUT, "w", encoding="utf-8") as f:
        f.write(text)
    print("wrote {} templates to {}".format(len(templates), OUT))
    return 0


if __name__ == "__main__":
    sys.exit(main())
